"""Step 30 report: results/partA/step30_severity/results.md from results.json (no model calls)."""
import os, json, sys, platform, time, subprocess
from . import step30_severity as S
D = S.OUT; R = json.load(open(os.path.join(D, 'results.json'))); NAMES = dict(S.TEXT, image_medsam_oracle_box='image check, oracle-box MedSAM (Step 16 masks)', image_unet_label_free='image check, label-free U-Net (Step 29)')
def a(c):
    if not c or not c['auroc']: return '—'
    v = c['auroc']; return f"{v[0]:.2f} ({v[1]:.2f}–{v[2]:.2f})" + (' †' if c['too_small'] else '')
def rho(c):
    if not c or not c['spearman']: return '—'
    v = c['spearman']; return f"{v[0]:.2f} ({v[1]:.2f}–{v[2]:.2f})" + (' †' if c['too_small'] else '')
ORGS = [('breast', 'breast'), ('thyroid', 'thyroid'), ('fetal head', 'fetal head'), ('ALL', 'pooled')]; HT = ('small', 'matched', 'large')
g = lambda n, o, s, h: R['auroc'][n][f'{o}|{s}|{h}']
md = ['# Step 30: severity breakdown (saved scores only)', '',
      'Limitations: [docs/LIMITATIONS.md](../../../docs/LIMITATIONS.md). Code: `usmeta/step30_severity.py`, `step30_report.py` (new files, no model call). Test split from saved scores (`bench_test_v2d.jsonl`, `scores_test_layer0/1.json`, judge replies of Steps 10d + 12) and, for the image check, `bench_v2d.jsonl` rows of the 228 scans of Steps 21a / 24 re-scored per candidate from SAVED masks (Step 16 oracle-box MedSAM and the Step 29 U-Net); no judge, writer or segmentation model was run.', '',
      '**Severity is our own provisional label (1 minor, 2 major, 3 critical), assigned by rule from the error type, not confirmed by any clinician.** It is also **confounded with error type**: level 3 is mostly lesion present/absent, pathology, side and BI-RADS/TI-RADS jumps; level 1 is orientation, position, small size and small category shifts (field counts per level are in `results.json`). It is also confounded with how much text the edit changes (the "no focal lesion" rewrite is level 3 and 40%+ of the text; Step 21e).', '',
      '**Method.** Per case, AUROC of the planted errors of one severity level against the harmless rewordings of one type (small / matched / large) of the same reference (ties 0.5); 95% CI by group bootstrap (1,000 resamples, seed 0); † = under 30 groups: too small to compare. Spearman = correlation between severity (1-3) and score drop (1 - score; identical copies score 1.0) over all error rows, CI by group bootstrap. Judge rows use the judged subset (59 cases per dataset); image-check rows use only errors in mask-checkable fields (lesion, count, position, orientation, size) on the 228 scans (breast and thyroid; fetal head is not in that scan set), and harmless rewordings state the same facts so they all score 1.0 (the three harmless columns of the image check are therefore the same).', '']
# headline numbers
sp = lambda n, o: R['spearman'][n][o]['spearman'][0] if R['spearman'][n][o]['spearman'] else float('nan')
md += ['## Headline', '',
       f"- **Severity does not order the word scorers the way a clinician would.** Their drop correlates only weakly with severity: Spearman {min(sp(n, 'ALL') for n in ('bleu', 'rougeL', 'chrf', 'bertscore[roberta-large]', 'ratescore')):.2f}-{max(sp(n, 'ALL') for n in ('bleu', 'rougeL', 'chrf', 'bertscore[roberta-large]', 'ratescore')):.2f} pooled (BLEU {sp('bleu', 'ALL'):.2f}, ROUGE-L {sp('rougeL', 'ALL'):.2f}, chrF {sp('chrf', 'ALL'):.2f}, BERTScore {sp('bertscore[roberta-large]', 'ALL'):.2f}, RaTEScore {sp('ratescore', 'ALL'):.2f}), and that correlation comes mostly from edit size (level 3 contains the whole-report rewrite), not from clinical weight. Against a matched one-word synonym BLEU is {g('bleu', 'breast', 1, 'matched')['auroc'][0]:.2f} / {g('bleu', 'breast', 2, 'matched')['auroc'][0]:.2f} / {g('bleu', 'breast', 3, 'matched')['auroc'][0]:.2f} on breast for levels 1 / 2 / 3: flat. Against the small and large harmless groups the pooled AUROC of the word scorers is 0.00-0.50 at levels 1 and 2 (they prefer the error; RaTEScore reaches 0.47-0.50 vs small), and rises at level 3 (vs small 0.55-0.75 pooled, see the tables) only because of the whole-report rewrite.",
       f"- **Critical errors look safer to the word scorers against small harmless rewordings, but that is the rewrite, not severity.** Against small harmless: breast BLEU {g('bleu', 'breast', 1, 'small')['auroc'][0]:.2f} / {g('bleu', 'breast', 2, 'small')['auroc'][0]:.2f} / {g('bleu', 'breast', 3, 'small')['auroc'][0]:.2f} and thyroid chrF {g('chrf', 'thyroid', 1, 'small')['auroc'][0]:.2f} / {g('chrf', 'thyroid', 2, 'small')['auroc'][0]:.2f} / {g('chrf', 'thyroid', 3, 'small')['auroc'][0]:.2f} for levels 1 / 2 / 3 (thyroid level 3 is 0.90 for every word scorer): level 3 contains the 'No focal lesion / nodule is seen.' text, which differs from the reference in almost every word. Even against the matched synonym the thyroid level-3 value is high (chrF {g('chrf', 'thyroid', 1, 'matched')['auroc'][0]:.2f} / {g('chrf', 'thyroid', 2, 'matched')['auroc'][0]:.2f} / {g('chrf', 'thyroid', 3, 'matched')['auroc'][0]:.2f}), because the error text is itself the much larger edit; in breast, where level 3 mixes rewrites with side / pathology / BI-RADS errors, BLEU vs matched stays flat (see the first bullet).",
       f"- **The Gemma judge's AUROC rises with severity and is weakest on levels 1-2.** Pooled `judge_score` AUROC vs small {g('judge_score', 'ALL', 1, 'small')['auroc'][0]:.2f} / {g('judge_score', 'ALL', 2, 'small')['auroc'][0]:.2f} / {g('judge_score', 'ALL', 3, 'small')['auroc'][0]:.2f} (levels 1 / 2 / 3), Spearman {sp('judge_score', 'ALL'):.2f}; breast sentence_f1 vs small is {g('sentence_f1', 'breast', 1, 'small')['auroc'][0]:.2f} / {g('sentence_f1', 'breast', 2, 'small')['auroc'][0]:.2f} / {g('sentence_f1', 'breast', 3, 'small')['auroc'][0]:.2f}.",
       f"- **`finding_f1` is 1.00 at every level (upper bound on templated text).** Its Spearman with severity is {sp('finding_f1', 'breast'):.2f} (breast), {sp('finding_f1', 'thyroid'):.2f} (thyroid), {sp('finding_f1', 'fetal head'):.2f} (fetal head): the fact check scores a larger number change lower in fetal head (graded credit), and otherwise treats every wrong fact alike.",
       f"- **The image check is best at the critical level and lowest at levels 1-2 (level 2 for oracle-box MedSAM, level 1 for the U-Net).** Pooled AUROC {g('image_medsam_oracle_box', 'ALL', 1, 'small')['auroc'][0]:.2f} / {g('image_medsam_oracle_box', 'ALL', 2, 'small')['auroc'][0]:.2f} / {g('image_medsam_oracle_box', 'ALL', 3, 'small')['auroc'][0]:.2f} (oracle-box MedSAM) and {g('image_unet_label_free', 'ALL', 1, 'small')['auroc'][0]:.2f} / {g('image_unet_label_free', 'ALL', 2, 'small')['auroc'][0]:.2f} / {g('image_unet_label_free', 'ALL', 3, 'small')['auroc'][0]:.2f} (label-free U-Net) for levels 1 / 2 / 3, because level 3 is mostly lesion-presence errors (a lesion that is there or not is easy to see), while levels 1-2 are position, orientation and size changes. Thyroid with the U-Net at level 1 is {g('image_unet_label_free', 'thyroid', 1, 'small')['auroc'][0]:.2f}. This is an error-type effect as much as a severity effect.", '',
       '## Cases per severity level (planted-error rows; groups = patients / exams or image ids)', '', '| organ | level 1 | level 2 | level 3 |', '|---|---|---|---|']
for o in ('breast', 'thyroid', 'fetal head'): md.append(f"| {o} | " + ' | '.join(f"{R['counts'][f'{o}|{s}']['error_rows']} rows, {R['counts'][f'{o}|{s}']['groups']} groups" for s in (1, 2, 3)) + ' |')
md += ['', 'Image check (228 scans, checkable fields only): ' + '; '.join(f"{k.replace('|', ' level ')}: {v['error_rows']} rows / {v['cases']} cases" for k, v in R['image_counts'].items()) + '.', '',
       '## Spearman between severity and score drop (all planted-error rows)', '', '| scorer | breast | thyroid | fetal head | pooled |', '|---|---|---|---|---|']
for n in R['spearman']: md.append(f"| {NAMES[n]} | " + ' | '.join(rho(R['spearman'][n][o]) for o, _ in ORGS) + ' |')
md += ['', 'Positive = a more severe error gets a bigger drop (good). † = under 30 groups. Fetal head has no image-check rows (HC18 / FetalHead are not in the 228 scans).', '']
for o, on in ORGS:
    for h in HT:
        md += [f'## AUROC vs harmless {h}: {on}', '', '| scorer | level 1 (minor) | level 2 (major) | level 3 (critical) |', '|---|---|---|---|']
        for n in R['auroc']:
            if o == 'fetal head' and n.startswith('image'): continue
            md.append(f"| {NAMES[n]} | " + ' | '.join(a(g(n, o, s, h)) for s in (1, 2, 3)) + ' |')
        md.append('')
md += ['## Caveats', '',
       '- **Severity is provisional and author-assigned** (never clinician-confirmed), and it is confounded with error type and with edit size, so no cell isolates "how bad" from "what kind" or "how many words changed". A clinician-confirmed ladder could reorder it.',
       '- **Judge rows** use the judged subset only (59 cases per dataset); some cells have fewer than 30 groups (marked †). One judge model, one prompt.',
       '- **Image-check rows** exclude non-checkable fields (BI-RADS, pathology, side, echo, margin, ...) by construction, so level 2 and 3 there are the checkable subset (level 3 is almost only lesion presence). Fetal head is not covered. The three harmless columns coincide.',
       '- Fetal head severity is set by the size of the HC error (level 1 small, 3 large) plus plane errors; the word scorers are flat across levels there because a changed number is one token whatever its size.',
       '- Per-case AUROC pools all errors of a level in a case; breast and thyroid have far more groups than fetal head. Pooled rows mix organs with different error mixes.', '']
open(os.path.join(D, 'results.md'), 'w').write('\n'.join(md))
def gg(*c):
    try: return subprocess.check_output(c, text=True, cwd=S.ROOT).strip()
    except Exception: return None
json.dump(dict(step='30', saved_scores_only=True, git_head_at_report=gg('git', 'rev-parse', '--short', 'HEAD'), python=sys.version.split()[0], platform=platform.platform(), date=time.strftime('%Y-%m-%d'), bootstrap='group, 1000 resamples, seed 0', min_groups=30), open(os.path.join(D, 'run_info.json'), 'w'), indent=1); print('wrote', len(md))
